window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-427b3e0e40ad71f1"]={"versions": [{"id": "FIG-427b3e0e40ad71f1", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des ECU-Konfigurationsmodells (ECUC Parameter Configuration) des AUTOSAR Classic BSW-Moduls RAM Test (<code>RamTst</code>). Das Metamodell definiert die strukturelle Zerlegung des Moduls in Konfigurationscontainer und Parameter zur Auswahl unterstützter RAM-Testalgorithmen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Metaklassen und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>RamTst : EcucModuleDef</code> (Kardinalität <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>) aggregiert über die Kompositionsrolle <code>+container</code> den Container <code>RamTstCommon</code>.\n</li><li><code>RamTstCommon : EcucParamConfContainerDef</code> (Kardinalität <code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code>) fungiert als übergeordneter Konfigurationscontainer und aggregiert über <code>+subContainer</code> den Sub-Container <code>RamTstAlgorithms</code>.\n</li><li><code>RamTstAlgorithms : EcucParamConfContainerDef</code> (Kardinalität <code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code>) aggregiert über Kompositionskanten mit der Rolle <code>+parameter</code> sechs boolesche Konfigurationsparameter vom Typ <code>EcucBooleanParamDef</code>:\n<ul class=\"fig-list\"><li><code>RamTstGalpatTestSelected</code>\n</li><li><code>RamTstTranspGalpatTestSelected</code>\n</li><li><code>RamTstAbrahamTestSelected</code>\n</li><li><code>RamTstCheckerboardTestSelected</code>\n</li><li><code>RamTstMarchTestSelected</code>\n</li><li><code>RamTstWalkPathTestSelected</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurations- und Datenmodell ohne Laufzeitinteraktion oder Sequenzabläufe. Die booleschen Parameter steuern zur Vorkompilier- bzw. Konfigurationszeit, welche spezifischen Prüfalgorithmen (GALPAT, transparentes GALPAT, Abraham-Test, Checkerboard, March-Test, Walkpath) im BSW-Modul <code>RamTst</code> einkompiliert und zur Laufzeit ausführbar sind.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives Konfigurationsmetamodell gemäß AUTOSAR-SWS RAM Test (<code>ECUC_RamTst_00066</code>). Integratoren und BSW-Konfiguratoren müssen den Container <code>RamTstAlgorithms</code> genau einmal innerhalb von <code>RamTstCommon</code> instanziieren (<code>[1..1]</code>). Die einzelnen Testselektionsparameter schalten die entsprechenden Algorithmen-Implementierungen im Treiber frei; mindestens die vom Sicherheitskonzept geforderten Algorithmen müssen auf <code>true</code> gesetzt werden, um die statische Codegenerierung passend zu steuern.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-abb89e90483be136", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des ECU-Konfigurationsmodells (ECUC Parameter Configuration) des AUTOSAR Classic BSW-Moduls RAM Test (<code>RamTst</code>). Das Metamodell definiert die strukturelle Zerlegung des Moduls in Konfigurationscontainer und Parameter zur Auswahl unterstützter RAM-Testalgorithmen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Metaklassen und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>RamTst : EcucModuleDef</code> (Kardinalität <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>) aggregiert über die Kompositionsrolle <code>+container</code> den Container <code>RamTstCommon</code>.\n</li><li><code>RamTstCommon : EcucParamConfContainerDef</code> (Kardinalität <code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code>) fungiert als übergeordneter Konfigurationscontainer und aggregiert über <code>+subContainer</code> den Sub-Container <code>RamTstAlgorithms</code>.\n</li><li><code>RamTstAlgorithms : EcucParamConfContainerDef</code> (Kardinalität <code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code>) aggregiert über Kompositionskanten mit der Rolle <code>+parameter</code> sechs boolesche Konfigurationsparameter vom Typ <code>EcucBooleanParamDef</code>:\n<ul class=\"fig-list\"><li><code>RamTstGalpatTestSelected</code>\n</li><li><code>RamTstTranspGalpatTestSelected</code>\n</li><li><code>RamTstAbrahamTestSelected</code>\n</li><li><code>RamTstCheckerboardTestSelected</code>\n</li><li><code>RamTstMarchTestSelected</code>\n</li><li><code>RamTstWalkPathTestSelected</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurations- und Datenmodell ohne Laufzeitinteraktion oder Sequenzabläufe. Die booleschen Parameter steuern zur Vorkompilier- bzw. Konfigurationszeit, welche spezifischen Prüfalgorithmen (GALPAT, transparentes GALPAT, Abraham-Test, Checkerboard, March-Test, Walkpath) im BSW-Modul <code>RamTst</code> einkompiliert und zur Laufzeit ausführbar sind.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives Konfigurationsmetamodell gemäß AUTOSAR-SWS RAM Test (<code>ECUC_RamTst_00066</code>). Integratoren und BSW-Konfiguratoren müssen den Container <code>RamTstAlgorithms</code> genau einmal innerhalb von <code>RamTstCommon</code> instanziieren (<code>[1..1]</code>). Die einzelnen Testselektionsparameter schalten die entsprechenden Algorithmen-Implementierungen im Treiber frei; mindestens die vom Sicherheitskonzept geforderten Algorithmen müssen auf <code>true</code> gesetzt werden, um die statische Codegenerierung passend zu steuern.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-427b3e0e40ad71f1", "to": "FIG-abb89e90483be136", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
